SELECT id, scope_type, scope_id, purpose, key_id, key_algorithm, data_algorithm,
       encrypted_data_key, ciphertext, created_at, updated_at, rotated_at
FROM secret_value


    scope_type = #{scopeType}


    AND scope_id = #{scopeId}


ORDER BY id

SELECT id, scope_type, scope_id, purpose, key_id, key_algorithm, data_algorithm,
       encrypted_data_key, ciphertext, created_at, updated_at, rotated_at
FROM secret_value
WHERE BINARY key_id != BINARY #{activeKeyId}
ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE secret_value
SET key_id = #{secret.keyId},
    key_algorithm = #{secret.keyAlgorithm},
    data_algorithm = #{secret.dataAlgorithm},
    encrypted_data_key = #{secret.encryptedDataKey},
    ciphertext = #{secret.ciphertext},
    rotated_at = CURRENT_TIMESTAMP
WHERE id = #{secret.id}
  AND BINARY key_id = BINARY #{previousKeyId}
  AND BINARY encrypted_data_key = BINARY #{previousEncryptedDataKey}
  AND BINARY ciphertext = BINARY #{previousCiphertext}
